void frame_9547_0(Activation& scope) {
    scope["Mousedown"] = false;
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        if (_root["Star"][((_root["Playinglevel"] * 5) - 5) + scope["starnum"]] == true) {
            scope["gotstar"] = true;
        } else {
            scope["gotstar"] = false;
        }
        if (scope["starnum"] == 1 || _root["Star"][((_root["Playinglevel"] * 5) - 5) + scope["starnum"]] == true || _root["Star"][((_root["Playinglevel"] * 5) - 5) + (scope["starnum"] - 1)] == true) {
            if (scope.self["hitTest"](_root["_xmouse"], _root["_ymouse"], true)) {
                _root["Selected"] = scope["starnum"];
            }
            if (_root["Selected"] == scope["starnum"]) {
                //_root.Starnames.gotoAndStop((((_root.Playinglevel*5)-5)+starnum));
                _root["starname"] = _root["StarNameArray"][(((_root["Playinglevel"] * 5) - 5) + scope["starnum"])];
                _root["stardescription"] = _root["StarDescArray"][(((_root["Playinglevel"] * 5) - 5) + scope["starnum"])];
                nextFrame();
            } else {
                prevFrame();
            }
        } else {
            gotoAndStop(1);
        }
        //
        if (scope["Mousedown"] == true || Key["isDown"](Key["SPACE"]) || _root["KeyZ"]() || _root["KeyX"]()) {
            if (scope["starnum"] == 1 || _root["Star"][((_root["Playinglevel"] * 5) - 5) + scope["starnum"]] == true || _root["Star"][((_root["Playinglevel"] * 5) - 5) + (scope["starnum"] - 1)] == true) {
                if (_root["Selected"] == scope["starnum"] && _root["StartCourse"] == false) {
                    _root["Starnum"] = scope["starnum"];
                    _root["StartCourse"] = true;
                }
            }
        }
        scope["Mousedown"] = false;
        //
        return undefined;
    });
    scope["onMouseDown"] = scope.function([](Activation& scope) -> Value {
        if (strictNotEquals(_root["StartCourse"], true) && scope.self["hitTest"](_root["_xmouse"], _root["_ymouse"], true)) {
            scope["Mousedown"] = true;
        }
        return undefined;
    });
}

