//  Menu/Framerate Counter / layer 'Layer 2' / frame 1
void frame_797_0(Activation& scope) {
    if ((_root["_quality"] == "BEST" || _root["_quality"] == "HIGH") && _root["AutoQuality"] == true) {
        _root["Qualitynum"]--;
    }
    //
    scope["qn"] = _root["Qualitynum"];
    scope["qn2"] = 0;
    _root["_quality"] = _root["QualityArray"][scope["qn"]];
    //
    scope["time"] = getTimer();
    scope["count"] = 0;
    scope["frtxt"] = "fps: unknown";
    stop();
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        if (_root["PauseGame"] == false) {
            if (scope["count"]++ >= 4) {
                if (_root["_quality"] == "LOW") {
                    _root["Qualitynum"] = 0;
                } else if (_root["_quality"] == "MEDIUM") {
                    _root["Qualitynum"] = 1;
                } else if (_root["_quality"] == "HIGH") {
                    _root["Qualitynum"] = 2;
                } else if (_root["_quality"] == "BEST") {
                    _root["Qualitynum"] = 3;
                }
                scope["qn"] = _root["Qualitynum"];
                //
                scope["diff"] = Math["round"](10000 / (getTimer() - scope["time"]) * scope["count"]) / 10;
                scope["time"] = getTimer();
                scope["count"] = 0;
                //
                if (scope["diff"] < 10) {
                    scope["frtxt"] = "fps: 0" + scope["diff"];
                } else {
                    scope["frtxt"] = "fps: " + scope["diff"];
                }
                if (Math["round"](scope["diff"]) == scope["diff"]) {
                    scope["frtxt"] += ".0";
                }
                //
                //trace(qn)
                if (scope["diff"] / 32 < 0.7) {
                    scope["qn2"]--;
                } else if (scope["diff"] / 32 > 0.9) {
                    scope["qn2"]++;
                }
                if (scope["qn2"] > 30) {
                    scope["qn2"] = 0;
                    scope["qn"] = Math["min"](scope["qn"] + 1, 3);
                } else if (scope["qn2"] < -15) {
                    scope["qn2"] = 0;
                    scope["qn"] = Math["max"](scope["qn"] - 1, 0);
                }
                if (_root["AutoQuality"] == true) {
                    if (strictNotEquals(_root["_quality"], _root["QualityArray"][scope["qn"]])) {
                        _root["_quality"] = _root["QualityArray"][scope["qn"]];
                    }
                    //
                    _root["Qualitynum"] = scope["qn"];
                }
            }
        } else {
            if (scope["count"]++ >= 4) {
                scope["diff"] = Math["round"](10000 / (getTimer() - scope["time"]) * scope["count"]) / 10;
                scope["time"] = getTimer();
                scope["count"] = 0;
                //
                if (scope["diff"] < 10) {
                    scope["frtxt"] = "fps: 0" + scope["diff"];
                } else {
                    scope["frtxt"] = "fps: " + scope["diff"];
                }
                if (Math["round"](scope["diff"]) == scope["diff"]) {
                    scope["frtxt"] += ".0";
                }
            }
        }
        return undefined;
    });
}

