void frame_9298_0(Activation& scope) {
    scope["awave"] = 90;
    scope["a2"] = 0;
    scope["_alpha"] = 0;
    scope["anum"] = 1;
    scope["_xscale"] = 25;
    scope["_yscale"] = 25;
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        if (scope.self["hitTest"](_root["_xmouse"], _root["_ymouse"], false)) {
            scope["hl"] = true;
        } else {
            scope["hl"] = false;
        }
        if (scope["hl"] == true && strictNotEquals(scope["cl"], true)) {
            scope["a2"] = Math["min"](scope["a2"] + 3, 50);
            scope["_xscale"] += (130 - scope["_xscale"]) / 5;
            scope["_yscale"] = scope["_xscale"];
        } else if (strictNotEquals(scope["cl"], true)) {
            scope["_xscale"] += (100 - scope["_xscale"]) / 5;
            scope["_yscale"] = scope["_xscale"];
            scope["a2"] = Math["max"](scope["a2"] - 3, 0);
        } else {
            scope["_xscale"] += 5;
            scope["_yscale"] = scope["_xscale"];
        }
        if (scope["anum"] > 20) {
            scope["awave"] += 0.03;
            scope["_alpha"] = Math["min"](75 + (Math["sin"](scope["awave"]) * 30) + scope["a2"], 100);
        } else {
            scope["_xscale"] += (100 - scope["_xscale"]) / 5;
            scope["_yscale"] = scope["_xscale"];
            scope["anum"]++;
            scope["_alpha"] += (100 - scope["_alpha"]) / 5;
        }
        return undefined;
    });
    scope["onMouseDown"] = scope.function([](Activation& scope) -> Value {
        if (scope["hl"] == true) {
            //_root.nextFrame();
            scope["cl"] = true;
            _root["attachMovie"]("TitleScreenTransition", "Transition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", 225}, {"_y", 150}, {"trans", true}}));
        }
        return undefined;
    });
}

